using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;
using OpenAI;
using System.ComponentModel;
using System.Text.Json;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

var modelId = "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();

// Define tools
var tools = new ResearchTools();
var chatOptions = new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
    Tools = [
        AIFunctionFactory.Create(tools.SearchWeb),
        AIFunctionFactory.Create(tools.TakeNote),
        AIFunctionFactory.Create(tools.GetNotes),
    ],
};

// Create the agent
var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Description = "An agent that researches topics by searching the web and taking notes.",
    Instructions = """
        You are a research assistant. When given a topic:
        1. Search the web for relevant information (perform multiple searches with different queries to get comprehensive coverage).
        2. Take notes on key findings as you discover them.
        3. After gathering enough information, retrieve all your notes and provide a well-structured summary.
        Always cite your sources. Be thorough but concise.
        """,
};

// Run the agent
Console.WriteLine("=== Research Agent ===");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):");
Console.Write("> ");

while (Console.ReadLine() is { } input && !input.Equals("quit", StringComparison.OrdinalIgnoreCase))
{
    if (string.IsNullOrWhiteSpace(input))
    {
        Console.Write("> ");
        continue;
    }

    tools.ClearNotes();

    var history = new List<ChatMessage>
    {
        new(ChatRole.User, $"Research the following topic and provide a summary: {input}"),
    };

    var invokeOptions = new AgentInvokeOptions
    {
        MaximumIterations = 10,
        ChatOptions = chatOptions,
    };

    Console.WriteLine("\nResearching...\n");

    await foreach (var message in agent.InvokeStreamingAsync(history, invokeOptions))
    {
        if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
        {
            Console.Write(message.Text);
        }
    }

    Console.WriteLine("\n");
    Console.Write("> ");
}

Console.WriteLine("Goodbye!");

/// <summary>
/// Tools available to the research agent for web search and note-taking.
/// </summary>
sealed class ResearchTools
{
    private readonly List<string> _notes = [];

    [Description("Search the web for information on a query. Returns a list of search results with titles, snippets, and URLs.")]
    public Task<string> SearchWeb(
        [Description("The search query to look up on the web")] string query)
    {
        // Simulated web search results — replace with a real search API (e.g., Bing Search)
        var results = new[]
        {
            new { Title = $"Overview of {query}", Url = $"https://example.com/{Uri.EscapeDataString(query)}", Snippet = $"Comprehensive overview covering the key aspects of {query}, including history, current state, and future outlook." },
            new { Title = $"Latest developments in {query}", Url = $"https://news.example.com/{Uri.EscapeDataString(query)}", Snippet = $"Recent news and developments related to {query}, featuring expert analysis and industry trends." },
            new { Title = $"{query} - Research and Analysis", Url = $"https://research.example.com/{Uri.EscapeDataString(query)}", Snippet = $"In-depth research and data-driven analysis of {query}, with statistics and projections." },
        };

        return Task.FromResult(JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true }));
    }

    [Description("Save a research note. Use this to record important findings during research.")]
    public Task<string> TakeNote(
        [Description("The content of the note to save")] string note,
        [Description("The source URL or reference for this note")] string source)
    {
        _notes.Add($"[Source: {source}] {note}");
        return Task.FromResult($"Note saved. You now have {_notes.Count} note(s).");
    }

    [Description("Retrieve all saved research notes.")]
    public Task<string> GetNotes()
    {
        if (_notes.Count == 0)
            return Task.FromResult("No notes saved yet.");

        return Task.FromResult(string.Join("\n\n", _notes.Select((n, i) => $"Note {i + 1}: {n}")));
    }

    public void ClearNotes() => _notes.Clear();
}

